window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["planning"]={"title":"智能体规划：把目标变成可执行、可修订的状态图","subtitle":"从目标、前置条件、产物和完成谓词理解计划—执行分离、滚动规划、检查点与局部重规划。","thesis":"计划的价值不是提前写出最长步骤清单，而是把目标转成带<b>前置条件、可观察产物、完成谓词、风险与回退</b>的状态转移；环境变化后只重算受影响部分，而不是继续执行过期文本。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"S0 到 S4 的节点、依赖和预计 5/8/3/6/10 分钟","rule":"S3 必须等待两者","steps":"S1 与 S2 在 S0 后并行","interpretation":"关键路径为 S0→S1→S3→S4"}}],"formulas":[],"termReviews":[{"section":2,"reviewedAt":"2026-07-27","terms":[{"name":"diff","meaning":"文件或结构在执行前后发生的可审计差异","purpose":"把修改动作转换成可观察的世界状态证据","definitionEvidence":"退出码 diff 测试","purposeEvidence":"转成事实"}]},{"section":4,"reviewedAt":"2026-07-27","terms":[{"name":"DAG","meaning":"节点依赖方向明确且不存在循环的有向无环图","purpose":"表达可并行任务与必须等待的关键依赖","definitionEvidence":"依赖图案例","purposeEvidence":"并行就绪集、关键路径"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"可执行计划是带前置动作产物完成谓词和回退的状态图。","evidence":"输出带前置条件、动作、产物、完成谓词与回退的状态图"},"problem":{"answer":"它解决自然语言步骤清单为何无法说明真正完成和失败恢复。","evidence":"何时真的完成”和“失败回哪里"},"inputOutput":{"answer":"输入目标状态约束工具风险，输出可执行状态图。","evidence":"输入目标、当前世界状态、约束、工具和风险"},"mechanism":{"answer":"每个节点绑定前置动作产物谓词回退和外部观察。","evidence":"工具调用只是一项动作"},"interpretation":{"answer":"工具被调用只表示动作发生，不表示目标状态达成。","evidence":"不是目标完成"},"boundary":{"answer":"世界状态必须由外部观察证明而非模型宣称。","evidence":"世界状态必须由外部观察证明"}},{"section":2,"definition":{"answer":"规划器执行器观察器控制器分别负责图动作事实和状态转换。","evidence":"输出推进、重试、回退或局部重规划"},"problem":{"answer":"它解决为何不能让模型边想边直接修改所有状态。","evidence":"计划中写“完成”不能冒充真实完成"},"inputOutput":{"answer":"输入目标图节点结果观察，输出控制动作。","evidence":"输入目标约束、依赖图、就绪节点、执行结果和外部观察"},"mechanism":{"answer":"规划图执行就绪节点，观察转事实，控制器比较预期实际。","evidence":"观察器把退出码 diff 测试转成事实"},"interpretation":{"answer":"角色分离让每项产物和责任可追踪。","evidence":"规划器提出有限视野图"},"boundary":{"answer":"计划文字不能覆盖来自执行环境的事实状态。","evidence":"不能冒充真实完成"}},{"section":3,"definition":{"answer":"任务契约让执行和验收共享一个节点完成定义。","evidence":"输出执行器与验收者共享的节点定义"},"problem":{"answer":"它解决怎样避免跑过测试被误当成测试通过。","evidence":"“我已理解”不是谓词"},"inputOutput":{"answer":"输入前置动作产物谓词回退批准，输出契约。","evidence":"输入前置事实、限定动作、可观察产物、机器完成谓词、回退和批准主体"},"mechanism":{"answer":"缓存节点绑定复现修改 diff 双测试和完成条件。","evidence":"修改 key、产出 diff 与双测试"},"interpretation":{"answer":"完成谓词检查世界状态而不是聊天中的自我报告。","evidence":"以两组测试通过为完成"},"boundary":{"answer":"高风险节点必须另声明批准主体与禁止状态。","evidence":"还要声明禁止状态"}},{"section":4,"definition":{"answer":"依赖图表示任务节点先后并行和关键路径。","evidence":"输出并行就绪集、关键路径和最早完成 29 分钟"},"problem":{"answer":"它解决哪些步骤可并行哪些必须等待证据。","evidence":"S3 必须等待两者"},"inputOutput":{"answer":"输入节点依赖时长，输出就绪路径和最早完成。","evidence":"输入 S0 到 S4 的节点、依赖和预计 5/8/3/6/10 分钟"},"mechanism":{"answer":"S1 S2 并行，S3 等两者，S4 等 S3。","evidence":"S1 与 S2 在 S0 后并行"},"interpretation":{"answer":"关键路径决定二十九分钟而非串行三十二分钟。","evidence":"关键路径为 S0→S1→S3→S4"},"boundary":{"answer":"验收失败只作废受补丁影响的下游节点。","evidence":"不重复已验证调查"}},{"section":5,"definition":{"answer":"滚动规划近处具体远处粗略并随新观察更新子图。","evidence":"输出近处具体节点、远处粗目标和新版本子图"},"problem":{"answer":"它解决未知环境为何不该预写死二十步细节。","evidence":"每到高不确定点再展开下一段"},"inputOutput":{"answer":"输入近远状态观察不变量，输出版本子图。","evidence":"输入近端已知状态、远端不确定依赖、新观察、目标与安全不变量"},"mechanism":{"answer":"执行到高不确定点后展开并只替换受影响部分。","evidence":"只替换受观察影响的子图"},"interpretation":{"answer":"计划版本记录触发证据与作废节点用于审计。","evidence":"记录触发证据和作废节点"},"boundary":{"answer":"新文本不能静默覆盖已验证事实与安全不变量。","evidence":"不能静默覆盖已验证事实"}},{"section":6,"definition":{"answer":"局部重规划按失败类型作废最小依赖子图并保留检查点。","evidence":"输出重试、回到事实来源、作废补丁子图或全面重规划"},"problem":{"answer":"它解决测试失败后重写完整计划造成重复劳动。","evidence":"重新制定完整计划”经常造成重复劳动"},"inputOutput":{"answer":"输入失败差异检查点依赖类型，输出恢复范围。","evidence":"输入失败节点、预期与实际差异、稳定检查点、依赖下游和失败类型"},"mechanism":{"answer":"瞬态重试事实错回源补丁错重做下游目标变才扩大。","evidence":"瞬态错误限次幂等重试"},"interpretation":{"answer":"更新范围随因果依赖而不是随文本段落决定。","evidence":"补丁副作用只重做补丁验收"},"boundary":{"answer":"已验证稳定产物不得被无关失败重复搜索覆盖。","evidence":"稳定产物用版本 ID 固定"}},{"section":7,"definition":{"answer":"规划方式按路径可知性选择工作流搜索 ToT 或 Agent。","evidence":"输出固定工作流、传统搜索、ToT 或 Agent 规划"},"problem":{"answer":"它解决是否所有长任务都需要语言模型规划器。","evidence":"固定分支用工作流"},"inputOutput":{"answer":"输入可知性动作空间动态反馈权限，输出规划方式。","evidence":"输入路径可预知性、动作空间、环境动态、工具反馈和风险权限"},"mechanism":{"answer":"已知分支工作流，可穷举搜索，未知动态才 Agent。","evidence":"可穷举候选用搜索"},"interpretation":{"answer":"工具真实反馈区分规划候选与已经发生的世界状态。","evidence":"未知环境路径才需要 Agent"},"boundary":{"answer":"权限事务幂等批准必须由外部系统强制。","evidence":"由外部系统强制"}},{"section":8,"definition":{"answer":"计划评测同时衡量成功可执行性恢复路径延迟和成本。","evidence":"输出最终成功、可执行率、前置错误、重复步骤、重规划、恢复距离、关键路径延迟和成本"},"problem":{"answer":"它解决怎样评估计划而不奖励漂亮长文本。","evidence":"调用翻倍而成功不变没有价值"},"inputOutput":{"answer":"输入三种执行方案轨迹，输出质量恢复成本指标。","evidence":"输入同任务的直接行动、固定工作流和规划器轨迹"},"mechanism":{"answer":"先静态检查 DAG 契约资源，再故障注入局部恢复。","evidence":"先静态检查工具存在、DAG 无环"},"interpretation":{"answer":"指标揭示计划是否减少错误重复和恢复距离。","evidence":"无效/重复步骤、重规划次数"},"boundary":{"answer":"成功不变而调用翻倍表示规划器没有创造价值。","evidence":"成功不变没有价值"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>把目标写成完成谓词；构造依赖 DAG；区分计划与执行状态；设计局部重规划和评测。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>步骤清单为什么还不是计划<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">“读代码—修改—测试—提交”看似完整，为什么仍可能第一步就走错？</p><p>自然语言清单没有说明读哪些文件、修改所依赖的事实、测试何时算通过、失败后回到哪里，也常把“调用工具”误写成“目标完成”。可执行计划必须引用当前状态，明确每一步的前置条件、动作、产物和机器可检查的完成谓词，并给每个状态变化留下可追溯证据。</p><div class=\"dd-note\"><b>区分：</b>目标是想达到的状态；计划是假设哪些动作能抵达它；执行观察才说明假设是否成立。</div><p>可执行计划输入目标、当前世界状态、约束、工具和风险，输出带前置条件、动作、产物、完成谓词与回退的状态图。它解决自然语言步骤清单无法说明“何时真的完成”和“失败回哪里”的问题；工具调用只是一项动作，不是目标完成。世界状态必须由外部观察证明。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>规划器、执行器与观察器怎样分工<span class=\"dd-badge eng\">机制</span></h2><p class=\"dd-lead\">为什么不让模型一边想一边直接改所有状态？</p><p>规划器读取目标、约束和已知状态，生成有限视野的依赖图；执行器只执行当前就绪节点；观察器把退出码、文件差异、测试结果等转成事实状态；控制器比较预期效果与实际观察，决定推进、重试、回退或重规划。分离产物可以防止“计划中写已完成”被误当成真实完成。</p><div class=\"dd-chain\">目标/禁止状态 → 依赖图 → 选择就绪节点 → 受限执行 → 观察与验证 → 更新状态 → 推进或局部重规划</div><p>角色分工输入目标约束、依赖图、就绪节点、执行结果和外部观察，输出推进、重试、回退或局部重规划。规划器提出有限视野图，执行器只跑就绪节点，观察器把退出码 diff 测试转成事实，控制器比较预期与实际。计划中写“完成”不能冒充真实完成。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>一个步骤应包含哪些字段<span class=\"dd-badge eng\">任务契约</span></h2><p class=\"dd-lead\">怎样让执行器和验收者对“完成”拥有同一含义？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>字段</th><th>缓存隔离修复示例</th><th>缺失风险</th></tr></thead><tbody><tr><td>前置条件</td><td>已复现跨用户串值；相关缓存代码已定位</td><td>凭猜测修改错误模块</td></tr><tr><td>动作/工具</td><td>最小补丁修改 key 构造</td><td>执行范围无限扩大</td></tr><tr><td>产物</td><td>补丁 diff + 隔离回归测试</td><td>只有聊天中的宣称</td></tr><tr><td>完成谓词</td><td>隔离测试与原命中测试均通过</td><td>把“跑过测试”当“测试通过”</td></tr><tr><td>回退</td><td>恢复该补丁并保留失败日志</td><td>失败后从头开始或叠加修改</td></tr></tbody></table></div><p>谓词应检查世界状态，例如文件哈希、测试计数、API 返回或批准记录；“我已经理解”“工具已调用”都不是完成谓词。高风险节点还要声明批准主体和禁止状态。</p><p>任务契约输入前置事实、限定动作、可观察产物、机器完成谓词、回退和批准主体，输出执行器与验收者共享的节点定义。缓存修复节点要求已复现串值、修改 key、产出 diff 与双测试，并以两组测试通过为完成；“我已理解”不是谓词。高风险节点还要声明禁止状态。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>怎样把修复任务画成依赖图<span class=\"dd-badge math\">运行示例</span></h2><p class=\"dd-lead\">哪些步骤能并行，哪些必须等待真实证据？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 680 260\" role=\"img\" aria-label=\"缓存隔离修复的依赖图和失败后的局部重规划\"><defs><marker id=\"pl1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"22\" y=\"95\" width=\"110\" height=\"56\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"77\" y=\"118\" text-anchor=\"middle\" class=\"svg-t\">S0 复现缺陷</text><text x=\"77\" y=\"137\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">保存失败测试</text><path d=\"M132,123 L181,76\" stroke=\"#6b7484\" marker-end=\"url(#pl1)\"/><path d=\"M132,123 L181,171\" stroke=\"#6b7484\" marker-end=\"url(#pl1)\"/><rect x=\"183\" y=\"42\" width=\"126\" height=\"60\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"246\" y=\"66\" text-anchor=\"middle\" class=\"svg-t\">S1 定位 key 构造</text><text x=\"246\" y=\"86\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">产物：调用链</text><rect x=\"183\" y=\"143\" width=\"126\" height=\"60\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"246\" y=\"167\" text-anchor=\"middle\" class=\"svg-t\">S2 读缓存契约</text><text x=\"246\" y=\"187\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">产物：隔离/命中要求</text><path d=\"M309,72 L370,123\" stroke=\"#6b7484\" marker-end=\"url(#pl1)\"/><path d=\"M309,173 L370,123\" stroke=\"#6b7484\" marker-end=\"url(#pl1)\"/><rect x=\"372\" y=\"91\" width=\"126\" height=\"64\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"435\" y=\"116\" text-anchor=\"middle\" class=\"svg-t\">S3 实施最小补丁</text><text x=\"435\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">依赖 S1 + S2</text><path d=\"M498,123 L548,123\" stroke=\"#6b7484\" marker-end=\"url(#pl1)\"/><rect x=\"550\" y=\"82\" width=\"112\" height=\"82\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"606\" y=\"105\" text-anchor=\"middle\" class=\"svg-t\">S4 验收</text><text x=\"606\" y=\"125\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">隔离 + 命中</text><text x=\"606\" y=\"144\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">全量回归</text><path d=\"M606,165 C602,235 435,238 435,157\" fill=\"none\" stroke=\"#c77b72\" marker-end=\"url(#pl1)\"/><text x=\"520\" y=\"229\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">若命中测试失败：保留 S0–S2，只重规划 S3，不重复已验证调查</text></svg><figcaption>图 1　依赖图显示 S1 与 S2 可并行，S3 必须等待两者；验收失败只使补丁节点失效，不应把已验证的复现和契约调查全部清零。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>节点</th><th>预计 5/8/3/6/10 分钟</th><th>依赖</th><th>最早完成</th></tr></thead><tbody><tr><td>S0 复现</td><td>5</td><td>无</td><td>5</td></tr><tr><td>S1 定位</td><td>8</td><td>S0</td><td>13</td></tr><tr><td>S2 契约</td><td>3</td><td>S0</td><td>8</td></tr><tr><td>S3 补丁</td><td>6</td><td>S1、S2</td><td>19</td></tr><tr><td>S4 验收</td><td>10</td><td>S3</td><td>29</td></tr></tbody></table></div><p>串行相加是 32 分钟；S1 与 S2 并行后，关键路径为 S0→S1→S3→S4，即 <code>5+8+6+10=29</code> 分钟。并行只节省不在关键路径上的 3 分钟，不能把强依赖任务宣传成任意加速。</p><p>依赖图案例输入 S0 到 S4 的节点、依赖和预计 5/8/3/6/10 分钟，输出并行就绪集、关键路径和最早完成 29 分钟。S1 与 S2 在 S0 后并行，S3 必须等待两者，S4 等待 S3；关键路径为 S0→S1→S3→S4。验收失败只作废补丁下游，不重复已验证调查。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>为什么采用滚动时域规划<span class=\"dd-badge eng\">不确定性</span></h2><p class=\"dd-lead\">环境越未知，为什么越不该预先写死二十步细节？</p><p>近处步骤有足够状态可写得具体，远处步骤依赖尚未发生的工具输出，只能保留粗目标和预算。执行到新的高不确定点后再展开下一段，类似滚动时域控制。这样减少过期计划，也避免模型为了填满清单而虚构文件、接口或结果。</p><p>每次滚动更新应保留目标和安全不变量，只替换受新观察影响的子图；计划版本记录触发证据和作废节点，便于审计。若新观察与旧状态冲突，先标记冲突并确定权威来源，不能让最后写入的文本静默覆盖已验证事实。</p><p>滚动规划输入近端已知状态、远端不确定依赖、新观察、目标与安全不变量，输出近处具体节点、远处粗目标和新版本子图。每到高不确定点再展开下一段，只替换受观察影响的子图，并记录触发证据和作废节点。新文本不能静默覆盖已验证事实。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>失败后怎样局部重规划<span class=\"dd-badge intuition\">恢复</span></h2><p class=\"dd-lead\">测试失败时，为什么“重新制定完整计划”经常造成重复劳动？</p><p>先比较节点的预期效果与实际观察：工具暂时失败可按幂等策略重试；前置条件不成立则回到产生它的最近节点；补丁不满足谓词则只作废该补丁及下游；目标或禁止状态变化才需要更大范围重规划。已验证产物用稳定 id 和版本固定，避免模型重复搜索和覆写。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>失败类型</th><th>更新范围</th><th>例子</th></tr></thead><tbody><tr><td>执行瞬态错误</td><td>当前节点</td><td>测试进程超时，限次重试</td></tr><tr><td>前置事实错误</td><td>事实来源及其下游</td><td>实际使用二级缓存，重新定位调用链</td></tr><tr><td>补丁副作用</td><td>补丁和验收节点</td><td>隔离修好但命中率归零</td></tr><tr><td>目标改变</td><td>重新检查全部依赖</td><td>从单租户修复变为跨区域一致性迁移</td></tr></tbody></table></div><p>局部重规划输入失败节点、预期与实际差异、稳定检查点、依赖下游和失败类型，输出重试、回到事实来源、作废补丁子图或全面重规划。瞬态错误限次幂等重试，前置事实错则回最近来源，补丁副作用只重做补丁验收，目标变化才扩大范围。稳定产物用版本 ID 固定。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>计划什么时候应让位于工作流或搜索<span class=\"dd-badge intuition\">边界</span></h2><p class=\"dd-lead\">所有长任务都需要语言模型规划器吗？</p><p>步骤固定、分支已知、失败语义稳定时，确定性工作流更便宜、更可测；候选动作明确且可穷举时，可用思维树或传统搜索；环境路径未知且工具反馈会改变决策时，Agent 规划才有价值。规划器不能替代工具权限、事务、幂等和人工批准。</p><div class=\"dd-note warn\"><b>失败边界：</b>文本计划中的“文件已备份”“用户已批准”只是字符串。控制器必须从文件系统、审批服务或工具返回读取真实状态，模型不能自行宣布高风险前置条件成立。</div><p>规划边界输入路径可预知性、动作空间、环境动态、工具反馈和风险权限，输出固定工作流、传统搜索、ToT 或 Agent 规划。固定分支用工作流，可穷举候选用搜索，未知环境路径才需要 Agent；无论哪种，权限事务幂等批准由外部系统强制。文本中的已备份或已批准不是事实。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>怎样评估计划而不奖励漂亮文本<span class=\"dd-badge math\">评测</span></h2><p class=\"dd-lead\">最终成功之外，哪些指标能暴露计划本身的缺陷？</p><p>对同一任务比较直接行动、固定工作流与规划器，报告最终成功、计划可执行率、前置条件错误、无效/重复步骤、重规划次数、从失败点到恢复点的距离、关键路径延迟和总成本。若规划器把 8 个工具调用变成 20 个而成功率不变，它没有创造价值。</p><p>可做“计划执行前静态检查”：引用的工具是否存在、依赖图是否有环、每个节点是否有产物和谓词、并行节点是否竞争同一资源；再用故障注入检查局部恢复。</p><p>计划评测输入同任务的直接行动、固定工作流和规划器轨迹，输出最终成功、可执行率、前置错误、重复步骤、重规划、恢复距离、关键路径延迟和成本。先静态检查工具存在、DAG 无环、节点有产物谓词和并行资源，再故障注入验证局部恢复。漂亮长计划若调用翻倍而成功不变没有价值。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与路线</span></h2><p class=\"dd-lead\">计划是可编辑的外部状态，不是隐藏思维越长越聪明。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>步骤越多计划越完整</td><td>过度分解增加协调成本，重点是依赖与完成谓词</td></tr><tr><td>先把全程写细最稳</td><td>远期状态未知，应近处细、远处粗并滚动展开</td></tr><tr><td>工具调用成功等于节点完成</td><td>必须验证动作后的世界状态是否满足谓词</td></tr><tr><td>失败后重新开始最干净</td><td>应保留稳定检查点，仅作废受影响子图</td></tr><tr><td>规划器能负责安全</td><td>权限、审批和禁止状态必须由外部控制器强制</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>Agent 循环、工具调用、状态机、评测</td></tr><tr><td><b>本页核心</b></td><td>目标谓词、依赖 DAG、滚动规划、检查点和局部重规划</td></tr><tr><td>紧邻</td><td>ReAct、思维树、工作流编排、反思</td></tr><tr><td>工程延伸</td><td>多智能体、人在回路、代码执行、可观测性与权限治理</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义目标与禁止状态</li><li>标注前置条件和产物</li><li>构造依赖图与关键路径</li><li>只执行当前就绪节点</li><li>用真实观察更新状态</li><li>从稳定检查点局部重规划</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>步骤清单为何不是可执行计划？</li><li>规划状态和世界状态有何区别？</li><li>为什么远期计划应更粗？</li><li>补丁失败后应作废哪些节点？</li><li>何时固定工作流更合适？</li><li>假设“智能体规划：把目标变成可执行、可修订的状态图”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“智能体规划：把目标变成可执行、可修订的状态图”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>它通常缺前置条件、产物、完成谓词和回退。</li><li>前者是假设与意图，后者必须由环境观察证明。</li><li>它依赖尚未出现的信息，细化容易虚构和过期。</li><li>补丁及依赖其产物的下游，保留已验证调查。</li><li>步骤、分支和失败语义可预先描述时。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2305.04091\" target=\"_blank\" rel=\"noopener\">Plan-and-Solve Prompting</a>：先规划再求解</li><li><a href=\"https://arxiv.org/abs/2305.18323\" target=\"_blank\" rel=\"noopener\">ReWOO: Decoupling Reasoning from Observations</a>：计划与工具观察解耦</li><li><a href=\"https://arxiv.org/abs/2310.04406\" target=\"_blank\" rel=\"noopener\">Language Agent Tree Search</a>：规划、搜索与环境反馈</li><li><a href=\"https://arxiv.org/abs/2210.03629\" target=\"_blank\" rel=\"noopener\">ReAct</a>：行动—观察闭环</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
